import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        int[] a = new int[n], freq = new int[2001];
        for (int i = 0; i < n; i++) freq[a[i] = Integer.parseInt(st.nextToken())]++;
        int[] res = Arrays.stream(a).filter(x -> freq[2 * x] == 1).sorted().toArray();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) { if (i > 0) sb.append(' '); sb.append(res[i]); }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := next()
	a := make([]int, n)
	freq := make([]int, 2001)
	for i := range a {
		a[i] = next()
		freq[a[i]]++
	}
	var res []int
	for _, x := range a {
		if freq[2*x] == 1 {
			res = append(res, x)
		}
	}
	sort.Ints(res)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, x := range res {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(x))
	}
	w.WriteByte('\n')
}
